// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

/**
 * Gap-analysis B9: every tier of the leading-field sorter must agree on UNSIGNED long order — LMDB key order is
 * unsigned, and inline-encoded negative doubles set bit 63. The radix passes sort by unsigned bytes, but the small (≤96
 * element) insertion tier and the {@code isSorted} early-exit historically compared signed, so a 90-row batch and a
 * 200-row batch of the same values sorted differently.
 */
class LeadingFieldSortersTest {

	private static final long SIGN_BIT_SET = 0x8000_0000_0000_0001L;

	@Test
	void smallBatchInsertionTierSortsUnsigned() {
		long[] values = { SIGN_BIT_SET, 5L, 3L };
		int[] indices = { 0, 1, 2 };

		LeadingFieldSorters.lsdRadixSort(indices, values, values.length, new int[3], new long[3], new int[256],
				new int[256]);

		assertThat(values)
				.as("unsigned ascending: the sign-bit value is the largest key, not the smallest")
				.containsExactly(3L, 5L, SIGN_BIT_SET);
		assertThat(indices).containsExactly(2, 1, 0);
	}

	@Test
	void unsignedSortedInputTakesTheEarlyExitUnchanged() {
		long[] values = { 3L, 5L, SIGN_BIT_SET };
		int[] indices = { 0, 1, 2 };

		LeadingFieldSorters.lsdRadixSort(indices, values, values.length, new int[3], new long[3], new int[256],
				new int[256]);

		assertThat(values).as("already unsigned-sorted input stays untouched").containsExactly(3L, 5L, SIGN_BIT_SET);
		assertThat(indices).containsExactly(0, 1, 2);
	}

	@Test
	void smallAndLargeBatchesAgreeOnTheSameKeys() {
		int large = 200;
		long[] largeValues = new long[large];
		int[] largeIndices = new int[large];
		long[] smallValues = new long[90];
		int[] smallIndices = new int[90];
		for (int i = 0; i < large; i++) {
			// interleave positive and sign-bit-set keys
			largeValues[i] = (i % 3 == 0) ? SIGN_BIT_SET + i : i * 17L + 1;
			largeIndices[i] = i;
		}
		System.arraycopy(largeValues, 0, smallValues, 0, 90);
		for (int i = 0; i < 90; i++) {
			smallIndices[i] = i;
		}

		LeadingFieldSorters.lsdRadixSort(largeIndices, largeValues, large, new int[large], new long[large],
				new int[256], new int[256]);
		LeadingFieldSorters.lsdRadixSort(smallIndices, smallValues, 90, new int[90], new long[90], new int[256],
				new int[256]);

		for (int i = 1; i < large; i++) {
			assertThat(Long.compareUnsigned(largeValues[i - 1], largeValues[i]))
					.as("radix tier output is unsigned nondecreasing at " + i)
					.isLessThanOrEqualTo(0);
		}
		for (int i = 1; i < 90; i++) {
			assertThat(Long.compareUnsigned(smallValues[i - 1], smallValues[i]))
					.as("insertion tier output is unsigned nondecreasing at " + i)
					.isLessThanOrEqualTo(0);
		}
	}
}
